    # Overpainted cells lie in a repeated wallpaper. The unobscured surrounding
    # picture gives the periodic tile; recover matching phase via copies elsewhere.
    n, m = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Tile period inferred as 24: the pattern repeats with 180-degree symmetry.
    # Each 2 belongs to an overlay shape; use the analogous position in the
    # opposite half of the repeated motif where it is not obscured.
    for r in range(n):
        for c in range(m):
            if grid[r][c] == 2:
                for dr, dc in ((12,0),(-12,0),(0,12),(0,-12),(23-2*r,23-2*c)):
                    rr, cc = r+dr, c+dc
                    if 0<=rr<n and 0<=cc<m and grid[rr][cc] != 2:
                        out[r][c] = grid[rr][cc]
                        break
