def transform(grid):
    # The 2s are a mask on a background symmetric under 180-degree rotation.
    # Restore covered cells by their point-reflected partners. For the central
    # symmetric masked island, use reflection of row/column-local motif where possible.
    n, m = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(n):
        for c in range(m):
            if grid[r][c] == 2:
                candidates = ((n-1-r, m-1-c), (r, m-1-c), (n-1-r, c))
                for rr, cc in candidates:
                    if grid[rr][cc] != 2:
                        out[r][c] = grid[rr][cc]
                        break
    return out
